#include <iostream>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;

const int N = 50;
const int M = 50;
const int K = 50;
const int T = N + K + 1;
const int N_ = N * T + 1;
const int M_ = K + (M * 2 * K + N) * (T - 1);
const int INF = 0x3f3f3f3f;

#define LT(u, v)	(pi[u] < pi[v] || pi[u] == pi[v] && kk[u] < kk[v])

int pi[N_], kk[N_], bb[N_];
int pq[1 + N_], iq[N_], cnt;

int i2(int i) {
	return (i *= 2) > cnt ? 0 : i < cnt && LT(pq[i + 1], pq[i]) ? i + 1 : i;
}

void pq_up(int u) {
	int i, j;
	for (i = iq[u]; (j = i / 2) && LT(u, pq[j]); i = j)
		pq[iq[pq[j]] = i] = pq[j];
	pq[iq[u] = i] = u;
}

void pq_dn(int u) {
	int i, j;
	for (i = iq[u]; (j = i2(i)) && LT(pq[j], u); i = j)
		pq[iq[pq[j]] = i] = pq[j];
	pq[iq[u] = i] = u;
}

void pq_add(int u) {
	iq[u] = ++cnt;
	pq_up(u);
}

int pq_remove_first() {
	int u = pq[1], v = pq[cnt--];
	iq[v] = 1;
	pq_dn(v);
	return u;
}

struct EdgeNode {
	EdgeNode* next;
	int j;
} aa[N], aa_[N_];

void add(int i, int j) {
	static EdgeNode l91[M * 2], *l = l91;
	l->j = j;
	l->next = aa[i].next; aa[i].next = l++;
}

void add_(int i, int h) {
	static EdgeNode l91[M_ * 2], *l = l91;
	l->j = h;
	l->next = aa_[i].next; aa_[i].next = l++;
}

int n_, m_;
int uu[M_], vv[M_], uv[M_], cost[M_], cost_[M_];
int cc[M_ * 2];

void link(int u, int v, int cap, int cos) {
	int h = m_++;
	uu[h] = u, vv[h] = v, uv[h] = u ^ v;
	cost[h] = cos;
	cc[h << 1 ^ 0] = cap;
	add_(u, h << 1 ^ 0);
	add_(v, h << 1 ^ 1);
}

void dijkstra(int s) {
	fill(pi, pi + n_, INF);
	pi[s] = 0;
	pq_add(s);
	while (cnt) {
		EdgeNode *l;
		int u = pq_remove_first(), v;
		int h, h_, p, k = kk[u] + 1;
		for (l = aa_[u].next; l; l = l->next)
			if (cc[h_ = l->j]) {
				h = h_ >> 1;
				p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
				v = u ^ uv[h];
				if (pi[v] == INF) {
					pi[v] = p;
					kk[v] = k;
					bb[v] = h_;
					pq_add(v);
				} else if (pi[v] > p || (pi[v] == p && kk[v] > k)) {
					pi[v] = p;
					kk[v] = k;
					bb[v] = h_;
					pq_up(v);
				}
			}
	}
}

void push(int s, int t) {
	int u, h, h_;
	for (u = t; u != s; u ^= uv[h]) {
		h = (h_ = bb[u]) >> 1;
		cc[h_]--, cc[h_ ^ 1]++;
	}
}

int edmonds_karp(int s, int t) {
	int c, h;
	memcpy(cost_, cost, m_ * sizeof *cost);
	while (1) {
		dijkstra(s);
		if (pi[t] == INF) break;
		push(s, t);
		for (h = 0; h < m_; h++) {
			int u = uu[h], v = vv[h];
			if (pi[u] != INF && pi[v] != INF)
				cost_[h] += pi[u] - pi[v];
		}
	}
	c = 0;
	for (h = 0; h < m_; h++)
		c += cost[h] * cc[h << 1 ^ 1];
	return c;
}

int main() {
	vector<int> ii(K);
	int n, m, k, t, c, d, h, i, j, s, u, v, x;
	cin >> n >> m >> k >> c >> d;
	for (h = 0; h < k; h++) {
		cin >> ii[h];
		ii[h]--;
	}
	while (m--) {
		cin >> i >> j;
		i--; j--;
		add(i, j); add(j, i);
	}
	t = n + k + 1;
	n_ = n * t + 1;
	m_ = 0;
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			EdgeNode *l;
			u = i * t + s;
			for (l = aa[i].next; l; l = l->next) {
				j = l->j;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					link(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	for (i = 0; i < n; i++)
		for (s = 0; s < t - 1; s++) {
			u = i * t + s; v = u + 1;
			link(u, v, k, i == 0 ? 0 : c);
		}
	for (h = 0; h < k; h++)
		link(n_ - 1, ii[h] * t + 0, 1, 0);
	cout << edmonds_karp(n_ - 1, 0 * t + t - 1) << endl;
	return 0;
}
